6	@@ -0,0 +1,283 @@
7	+/*
8	+ * Harbor synthetic spec for OpenCTI-Platform__opencti-16540-mm.
9	+ *
10	+ * WHAT IT DRIVES
11	+ *   - the REAL DraftRoot page (private/components/drafts/DraftRoot.tsx), fed a draft fixture
12	+ *     through the relay boundary, which renders
13	+ *   - the REAL ConnectorWorkLine (private/components/data/connectors/ConnectorWorkLine.tsx) for
14	+ *     the draft's validation work, through the REAL Label / TaskStatus / Tag components, and
15	+ *   - the REAL ConnectorWorks list (the OTHER, generic call site of the very same work line, the
16	+ *     one used by the connectors screen) as the reference context.
17	+ *
18	+ * HOW IT ASSERTS
19	+ *   Never by looking for a string copied out of the fix. A work line is read back as a set of
20	+ *   {label, value} pairs; the status field is located by its VALUE (the work state that the line
21	+ *   is displaying) and the assertion is then made on that field's LABEL. The contract checked is
22	+ *   the observable mapping "which context am I in -> which wording labels the state field":
23	+ *   the draft page must label it with its own validation wording, the generic connectors page
24	+ *   must keep the platform's generic wording, and the two must not collapse onto one text.
25	+ *   The set of work states is read live out of the GraphQL schema's `enum State`, so the spec
26	+ *   follows the platform if a state is ever added or removed.
27	+ */
28	+import fs from 'node:fs';
29	+import path from 'node:path';
30	+import { fileURLToPath } from 'node:url';
31	+import React from 'react';
32	+import { describe, it, expect, afterEach } from 'vitest';
33	+import { render, cleanup } from '@testing-library/react';
34	+import DraftRoot from '../src/private/components/drafts/DraftRoot';
35	+import ConnectorWorks from '../src/private/components/data/connectors/ConnectorWorks';
36	+
37	+const here = path.dirname(fileURLToPath(import.meta.url));
38	+
39	+/* ------------------------------------------------------------------ work states, read live */
40	+
41	+const readWorkStates = () => {
42	+  const schemaPath = path.resolve(here, '../../opencti-graphql/config/schema/opencti.graphql');
43	+  const schema = fs.readFileSync(schemaPath, 'utf-8');
44	+  const block = schema.match(/\benum\s+State\s*\{([^}]*)\}/);
45	+  if (!block) throw new Error(`could not read "enum State" from ${schemaPath}`);
46	+  return block[1].split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('#'));
47	+};
48	+
49	+const WORK_STATES = readWorkStates();
50	+
51	+/* ----------------------------------------------------------------------------- DOM reading */
52	+
53	+// Every field of a work line is a Label (an <h6>) followed by the field value. Walk up from the
54	+// heading to the smallest ancestor that carries more text than the label itself: that node is
55	+// the field. Returns [{ label, value }] in document order.
56	+const fieldsIn = (root) => Array.from(root.querySelectorAll('h6')).map((heading) => {
57	+  const label = (heading.textContent || '').trim();
58	+  let node = heading;
59	+  for (let hop = 0; hop < 3; hop += 1) {
60	+    const parent = node.parentElement;
61	+    if (!parent || parent === root) break;
62	+    // Stop as soon as the parent carries more text than the label: that parent is the field.
63	+    if ((parent.textContent || '').trim() !== label) break;
64	+    node = parent;
65	+  }
66	+  const container = node.parentElement || node;
67	+  const text = (container.textContent || '').trim();
68	+  return { label, value: text.startsWith(label) ? text.slice(label.length).trim() : text };
69	+});
70	+
71	+const labelsIn = (root) => fieldsIn(root).map((f) => f.label);
72	+
73	+// The state field is the one whose displayed VALUE is the work state; its label is what the
74	+// spec is about.
75	+const stateFieldIn = (root, state) => {
76	+  const field = fieldsIn(root).find((f) => f.value === state);
77	+  if (!field) {
78	+    throw new Error(`no field displays the work state "${state}"; fields were ${JSON.stringify(fieldsIn(root))}`);
79	+  }
80	+  return field;
81	+};
82	+
83	+/* -------------------------------------------------------------------------------- fixtures */
84	+
85	+const makeWork = (state, overrides = {}) => ({
86	+  id: 'work-1',
87	+  name: 'Draft validation bundle',
88	+  received_time: '2026-02-03T10:11:12.000Z',
89	+  processed_time: '2026-02-03T10:12:00.000Z',
90	+  completed_time: '2026-02-03T10:13:30.000Z',
91	+  status: state,
92	+  tracking: { import_expected_number: 40, import_processed_number: 12 },
93	+  errors: [],
94	+  ...overrides,
95	+});
96	+
97	+const makeDraft = (work, overrides = {}) => ({
98	+  id: 'draft-1',
99	+  name: 'Q1 threat report draft',
100	+  entity_type: 'DraftWorkspace',
101	+  description: 'A draft under validation',
102	+  created_at: '2026-02-03T09:00:00.000Z',
103	+  objectAssignee: [],
104	+  objectParticipant: [],
105	+  createdBy: null,
106	+  objectsCount: {
107	+    containersCount: 1,
108	+    entitiesCount: 2,
109	+    observablesCount: 3,
110	+    relationshipsCount: 4,
111	+    sightingsCount: 5,
112	+    reviewsCount: 6,
113	+    totalCount: 21,
114	+  },
115	+  draft_status: 'validated', // anything but 'open' => the read-only, post-approval overview
116	+  currentUserAccessRight: 'admin',
117	+  authorizedMembers: [],
118	+  validationWork: work,
119	+  ...overrides,
120	+});
121	+
122	+/* --------------------------------------------------------------------------- render helpers */
123	+
124	+// Renders the REAL draft overview page and hands the caller its DOM.
125	+const inDraftPage = (work, draftOverrides, fn) => {
126	+  const draft = makeDraft(work, draftOverrides);
127	+  globalThis.__HARBOR_PARAMS__ = { draftId: draft.id };
128	+  globalThis.__HARBOR_PATHNAME__ = `/dashboard/data/import/draft/${draft.id}/entities`;
129	+  globalThis.__HARBOR_PRELOADED__ = { draftWorkspace: draft };
130	+  globalThis.__HARBOR_DRAFT_CONTEXT__ = null;
131	+  globalThis.__HARBOR_FEATURES__ = ['DRAFT_WORKFLOW'];
132	+  const { container, unmount } = render(<DraftRoot />);
133	+  try {
134	+    return fn(container);
135	+  } finally {
136	+    unmount();
137	+  }
138	+};
139	+
140	+// Renders the REAL connectors-screen list of works, i.e. the generic use of the same work line.
141	+const inConnectorsPage = (works, fn) => {
142	+  const data = { works: { edges: works.map((node) => ({ node })) } };
143	+  const { container, unmount } = render(
144	+    <ConnectorWorks data={data} options={[]} relay={{ refetch: () => {} }} inProgress />,
145	+  );
146	+  try {
147	+    return fn(container);
148	+  } finally {
