790	+  'private/components/drafts/DraftOverview': stub('noopComponent.jsx'),
791	+  'private/components/drafts/useSwitchDraft': stub('useSwitchDraft.js'),
792	+  'relay/environment': stub('relayEnvironment.js'),
793	+  'utils/Security': stub('security.jsx'),
