[metadata] {"type": "text", "file": {"filePath": "/app/task/tests/test.patch", "content": "diff --git a/opencti-platform/opencti-front/harbor_tests/draftValidationWorkLabel.test.jsx b/opencti-platform/opencti-front/harbor_tests/draftValidationWorkLabel.test.jsx\nnew file mode 100644\nindex 0000000..44b4046\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/draftValidationWorkLabel.test.jsx\n@@ -0,0 +1,283 @@\n+/*\n+ * Harbor synthetic spec for OpenCTI-Platform__opencti-16540-mm.\n+ *\n+ * WHAT IT DRIVES\n+ *   - the REAL DraftRoot page (private/components/drafts/DraftRoot.tsx), fed a draft fixture\n+ *     through the relay boundary, which renders\n+ *   - the REAL ConnectorWorkLine (private/components/data/connectors/ConnectorWorkLine.tsx) for\n+ *     the draft's validation work, through the REAL Label / TaskStatus / Tag components, and\n+ *   - the REAL ConnectorWorks list (the OTHER, generic call site of the very same work line, the\n+ *     one used by the connectors screen) as the reference context.\n+ *\n+ * HOW IT ASSERTS\n+ *   Never by looking for a string copied out of the fix. A work line is read back as a set of\n+ *   {label, value} pairs; the status field is located by its VALUE (the work state that the line\n+ *   is displaying) and the assertion is then made on that field's LABEL. The contract checked is\n+ *   the observable mapping \"which context am I in -> which wording labels the state field\":\n+ *   the draft page must label it with its own validation wording, the generic connectors page\n+ *   must keep the platform's generic wording, and the two must not collapse onto one text.\n+ *   The set of work states is read live out of the GraphQL schema's `enum State`, so the spec\n+ *   follows the platform if a state is ever added or removed.\n+ */\n+import fs from 'node:fs';\n+import path from 'node:path';\n+import { fileURLToPath } from 'node:url';\n+import React from 'react';\n+import { describe, it, expect, afterEach } from 'vitest';\n+import { render, cleanup } from '@testing-library/react';\n+import DraftRoot from '../src/private/components/drafts/DraftRoot';\n+import ConnectorWorks from '../src/private/components/data/connectors/ConnectorWorks';\n+\n+const here = path.dirname(fileURLToPath(import.meta.url));\n+\n+/* ------------------------------------------------------------------ work states, read live */\n+\n+const readWorkStates = () => {\n+  const schemaPath = path.resolve(here, '../../opencti-graphql/config/schema/opencti.graphql');\n+  const schema = fs.readFileSync(schemaPath, 'utf-8');\n+  const block = schema.match(/\\benum\\s+State\\s*\\{([^}]*)\\}/);\n+  if (!block) throw new Error(`could not read \"enum State\" from ${schemaPath}`);\n+  return block[1].split('\\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('#'));\n+};\n+\n+const WORK_STATES = readWorkStates();\n+\n+/* ----------------------------------------------------------------------------- DOM reading */\n+\n+// Every field of a work line is a Label (an <h6>) followed by the field value. Walk up from the\n+// heading to the smallest ancestor that carries more text than the label itself: that node is\n+// the field. Returns [{ label, value }] in document order.\n+const fieldsIn = (root) => Array.from(root.querySelectorAll('h6')).map((heading) => {\n+  const label = (heading.textContent || '').trim();\n+  let node = heading;\n+  for (let hop = 0; hop < 3; hop += 1) {\n+    const parent = node.parentElement;\n+    if (!parent || parent === root) break;\n+    // Stop as soon as the parent carries more text than the label: that parent is the field.\n+    if ((parent.textContent || '').trim() !== label) break;\n+    node = parent;\n+  }\n+  const container = node.parentElement || node;\n+  const text = (container.textContent || '').trim();\n+  return { label, value: text.startsWith(label) ? text.slice(label.length).trim() : text };\n+});\n+\n+const labelsIn = (root) => fieldsIn(root).map((f) => f.label);\n+\n+// The state field is the one whose displayed VALUE is the work state; its label is what the\n+// spec is about.\n+const stateFieldIn = (root, state) => {\n+  const field = fieldsIn(root).find((f) => f.value === state);\n+  if (!field) {\n+    throw new Error(`no field displays the work state \"${state}\"; fields were ${JSON.stringify(fieldsIn(root))}`);\n+  }\n+  return field;\n+};\n+\n+/* -------------------------------------------------------------------------------- fixtures */\n+\n+const makeWork = (state, overrides = {}) => ({\n+  id: 'work-1',\n+  name: 'Draft validation bundle',\n+  received_time: '2026-02-03T10:11:12.000Z',\n+  processed_time: '2026-02-03T10:12:00.000Z',\n+  completed_time: '2026-02-03T10:13:30.000Z',\n+  status: state,\n+  tracking: { import_expected_number: 40, import_processed_number: 12 },\n+  errors: [],\n+  ...overrides,\n+});\n+\n+const makeDraft = (work, overrides = {}) => ({\n+  id: 'draft-1',\n+  name: 'Q1 threat report draft',\n+  entity_type: 'DraftWorkspace',\n+  description: 'A draft under validation',\n+  created_at: '2026-02-03T09:00:00.000Z',\n+  objectAssignee: [],\n+  objectParticipant: [],\n+  createdBy: null,\n+  objectsCount: {\n+    containersCount: 1,\n+    entitiesCount: 2,\n+    observablesCount: 3,\n+    relationshipsCount: 4,\n+    sightingsCount: 5,\n+    reviewsCount: 6,\n+    totalCount: 21,\n+  },\n+  draft_status: 'validated', // anything but 'open' => the read-only, post-approval overview\n+  currentUserAccessRight: 'admin',\n+  authorizedMembers: [],\n+  validationWork: work,\n+  ...overrides,\n+});\n+\n+/* --------------------------------------------------------------------------- render helpers */\n+\n+// Renders the REAL draft overview page and hands the caller its DOM.\n+const inDraftPage = (work, draftOverrides, fn) => {\n+  const draft = makeDraft(work, draftOverrides);\n+  globalThis.__HARBOR_PARAMS__ = { draftId: draft.id };\n+  globalThis.__HARBOR_PATHNAME__ = `/dashboard/data/import/draft/${draft.id}/entities`;\n+  globalThis.__HARBOR_PRELOADED__ = { draftWorkspace: draft };\n+  globalThis.__HARBOR_DRAFT_CONTEXT__ = null;\n+  globalThis.__HARBOR_FEATURES__ = ['DRAFT_WORKFLOW'];\n+  const { container, unmount } = render(<DraftRoot />);\n+  try {\n+    return fn(container);\n+  } finally {\n+    unmount();\n+  }\n+};\n+\n+// Renders the REAL connectors-screen list of works, i.e. the generic use of the same work line.\n+const inConnectorsPage = (works, fn) => {\n+  const data = { works: { edges: works.map((node) => ({ node })) } };\n+  const { container, unmount } = render(\n+    <ConnectorWorks data={data} options={[]} relay={{ refetch: () => {} }} inProgress />,\n+  );\n+  try {\n+    return fn(container);\n+  } finally {\n+    unmount();\n+  }\n+};\n+\n+const draftStateLabel = (state, workOverrides = {}, draftOverrides = {}) => inDraftPage(\n+  makeWork(state, workOverrides),\n+  draftOverrides,\n+  (root) => stateFieldIn(root, state).label,\n+);\n+\n+const connectorStateLabel = (state, workOverrides = {}) => inConnectorsPage(\n+  [makeWork(state, workOverrides)],\n+  (root) => stateFieldIn(root, state).label,\n+);\n+\n+afterEach(() => {\n+  cleanup();\n+  delete globalThis.__HARBOR_PRELOADED__;\n+  delete globalThis.__HARBOR_PARAMS__;\n+  delete globalThis.__HARBOR_PATHNAME__;\n+});\n+\n+/* ------------------------------------------------------------------------------------ f2p */\n+\n+describe('Draft validation work status', () => {\n+  it('labels the validation work state of a draft differently from a plain connector work', () => {\n+    const collapsed = [];\n+    for (const state of WORK_STATES) {\n+      const inDraft = draftStateLabel(state);\n+      const generic = connectorStateLabel(state);\n+      expect(inDraft.length).toBeGreaterThan(0);\n+      if (inDraft === generic) collapsed.push({ state, label: inDraft });\n+    }\n+    expect(collapsed).toEqual([]);\n+  });\n+\n+  it('uses one and the same label for the validation work state whatever the state is', () => {\n+    const seen = WORK_STATES.map((state) => draftStateLabel(state));\n+    // A single wording, so the label describes the field and not the value inside it ...\n+    expect(Array.from(new Set(seen))).toHaveLength(1);\n+    // ... and that wording is the draft-specific one, not the generic connector one.\n+    expect(seen[0]).not.toBe(connectorStateLabel(WORK_STATES[0]));\n+  });\n+\n+  it('names the validation work state after the validation it reports on', () => {\n+    const label = draftStateLabel('complete');\n+    expect(label.toLowerCase()).toMatch(/validation/);\n+    expect(label.trim().toLowerCase()).not.toBe('status');\n+  });\n+\n+  it('labels the validation work state the same way for an unrelated draft', () => {\n+    // Second, disjoint data set: nothing about the wording may be tied to the values of the\n+    // draft or of the work that the report happened to show.\n+    const otherWork = {\n+      id: 'work-77',\n+      name: 'Bundle 4321 - partner feed',\n+      received_time: '2025-11-30T23:45:00.000Z',\n+      processed_time: '2025-12-01T00:02:00.000Z',\n+      completed_time: '',\n+      tracking: { import_expected_number: 9, import_processed_number: 9 },\n+      errors: [{ timestamp: '2025-12-01T00:01:00.000Z', message: 'boom', sequence: 1, source: 'x' }],\n+    };\n+    const otherDraft = {\n+      id: 'draft-99',\n+      name: 'Partner ingestion draft',\n+      draft_status: 'closed',\n+      objectsCount: {\n+        containersCount: 11,\n+        entitiesCount: 12,\n+        observablesCount: 13,\n+        relationshipsCount: 14,\n+        sightingsCount: 15,\n+        reviewsCount: 16,\n+        totalCount: 81,\n+      },\n+    };\n+    const label = draftStateLabel('progress', otherWork, otherDraft);\n+    expect(label).toBe(draftStateLabel('complete'));\n+    expect(label).not.toBe(connectorStateLabel('progress', otherWork));\n+  });\n+});\n+\n+/* ------------------------------------------------------------------------------------ p2p */\n+\n+describe('Draft validation work status (p2p guards)', () => {\n+  it('reads at least the wait, progress and complete work states from the platform schema', () => {\n+    // Guard for the specs that loop over whatever the schema declares.\n+    expect(WORK_STATES.length).toBeGreaterThanOrEqual(3);\n+    expect(WORK_STATES).toContain('complete');\n+  });\n+\n+  it('keeps the generic connector work line labelled with the platform status wording', () => {\n+    for (const state of WORK_STATES) {\n+      expect(connectorStateLabel(state)).toBe('Status');\n+    }\n+  });\n+\n+  it('leaves every other field label of the work line untouched in the draft context', () => {\n+    const state = 'complete';\n+    const draftLabels = inDraftPage(makeWork(state), {}, (root) => labelsIn(root));\n+    const genericLabels = inConnectorsPage([makeWork(state)], (root) => labelsIn(root));\n+    const draftStatus = draftStateLabel(state);\n+    const genericStatus = connectorStateLabel(state);\n+    expect(draftLabels.filter((l) => l !== draftStatus))\n+      .toEqual(genericLabels.filter((l) => l !== genericStatus));\n+    // The work line is more than its state field: name, timings, counters and progress.\n+    expect(genericLabels.length).toBeGreaterThanOrEqual(6);\n+  });\n+\n+  it('still shows the work state itself in both contexts', () => {\n+    for (const state of WORK_STATES) {\n+      expect(inDraftPage(makeWork(state), {}, (root) => stateFieldIn(root, state).value)).toBe(state);\n+      expect(inConnectorsPage([makeWork(state)], (root) => stateFieldIn(root, state).value)).toBe(state);\n+    }\n+  });\n+\n+  it('still shows the name, timings and counters of the draft validation work', () => {\n+    const work = makeWork('complete');\n+    const byLabel = inDraftPage(work, {}, (root) => Object.fromEntries(fieldsIn(root).map((f) => [f.label, f.value])));\n+    expect(byLabel.Name).toBe(work.name);\n+    expect(byLabel['Work start time']).toBe(work.received_time);\n+    expect(byLabel['Work end time']).toBe(work.completed_time);\n+    // Which of the two tracking counters feeds which counter field is a separate (pre-existing)\n+    // question, so assert on the pair rather than on the individual assignment.\n+    expect([byLabel['Operations completed'], byLabel['Total number of operations']].sort())\n+      .toEqual([String(work.tracking.import_expected_number), String(work.tracking.import_processed_number)].sort());\n+  });\n+\n+  it('renders one generic work line per work of the connectors screen', () => {\n+    const works = WORK_STATES.map((state, i) => makeWork(state, { id: `work-${i}`, name: `Bundle ${i}` }));\n+    inConnectorsPage(works, (root) => {\n+      const cards = Array.from(root.querySelectorAll('[data-harbor=\"card\"]'));\n+      expect(cards).toHaveLength(works.length);\n+      cards.forEach((card, i) => {\n+        const field = stateFieldIn(card, works[i].status);\n+        expect(field.label).toBe('Status');\n+        expect(fieldsIn(card).find((f) => f.label === 'Name').value).toBe(works[i].name);\n+      });\n+    });\n+  });\n+});\ndiff --git a/opencti-platform/opencti-front/harbor_tests/setup.js b/opencti-platform/opencti-front/harbor_tests/setup.js\nnew file mode 100644\nindex 0000000..bb02c60\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/setup.js\n@@ -0,0 +1 @@\n+import '@testing-library/jest-dom/vitest';\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/Button.jsx b/opencti-platform/opencti-front/harbor_tests/stubs/Button.jsx\nnew file mode 100644\nindex 0000000..e6c4f37\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/Button.jsx\n@@ -0,0 +1,6 @@\n+// Stand-in for the design-system @common/button/Button (the real one needs @mui/styles).\n+import React from 'react';\n+const Button = ({ children, variant, size, intent, gradient, iconOnly, startIcon, ...rest }) => (\n+  <button type=\"button\" {...rest}>{startIcon}{children}</button>\