eof Map || v instanceof Set) return v.size === 0;\n+  if (typeof v === 'object') return Object.keys(v).length === 0;\n+  return false;\n+};\n+export const uniq = (list) => Array.from(new Set(list || []));\n+export const last = (list) => (list && list.length ? list[list.length - 1] : undefined);\n+export const head = (list) => (list && list.length ? list[0] : undefined);\n+export const map = (fn, list) => (list === undefined ? (l) => (l || []).map(fn) : (list || []).map(fn));\n+export const filter = (fn, list) => (list === undefined ? (l) => (l || []).filter(fn) : (list || []).filter(fn));\n+export const includes = (needle, list) => (list === undefined ? (l) => (l || []).includes(needle) : (list || []).includes(needle));\n+export const mergeAll = (list) => Object.assign({}, ...(list || []));\n+export const pipe = (...fns) => (x) => fns.reduce((acc, fn) => fn(acc), x);\n+export const join = (sep, list) => (list === undefined ? (l) => (l || []).join(sep) : (list || []).join(sep));\n+export const split = (sep, s) => (s === undefined ? (v) => String(v).split(sep) : String(s).split(sep));\n+export const toPairs = (o) => Object.entries(o || {});\n+export const fromPairs = (p) => Object.fromEntries(p || []);\n+export const assoc = (k, v, o) => ({ ...(o || {}), [k]: v });\n+export const dissoc = (k, o) => { const c = { ...(o || {}) }; delete c[k]; return c; };\n+export const uniqBy = (fn, list) => {\n+  const seen = new Set();\n+  return (list || []).filter((x) => { const k = fn(x); if (seen.has(k)) return false; seen.add(k); return true; });\n+};\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/reactRelay.jsx b/opencti-platform/opencti-front/harbor_tests/stubs/reactRelay.jsx\nnew file mode 100644\nindex 0000000..b4e320a\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/reactRelay.jsx\n@@ -0,0 +1,35 @@\n+// Stand-in for `react-relay`: there is no relay runtime and no GraphQL server in the offline\n+// verifier image.\n+//\n+// usePreloadedQuery hands back the fixture the spec published on globalThis, so the REAL\n+// DraftRoot runs its own real fragment/branching logic over it. useFragment is the identity,\n+// which is exactly what relay does once the data is masked. createRefetchContainer is the\n+// identity too, so the REAL ConnectorWorks component (the generic connectors-page usage of\n+// ConnectorWorkLine) can be rendered directly.\n+export const graphql = (strings, ...exprs) => ({\n+  kind: 'Request',\n+  __harborGraphQL: String.raw({ raw: strings }, ...exprs),\n+});\n+\n+export const useFragment = (_node, data) => data;\n+export const usePreloadedQuery = () => (globalThis.__HARBOR_PRELOADED__ ?? {});\n+\n+const HARBOR_QUERY_REF = { __harborQueryRef: true };\n+export const useQueryLoader = () => [HARBOR_QUERY_REF, () => {}, () => {}];\n+\n+export const useMutation = () => {\n+  if (!globalThis.__HARBOR_MUTATIONS__) globalThis.__HARBOR_MUTATIONS__ = [];\n+  const commit = (args) => {\n+    globalThis.__HARBOR_MUTATIONS__.push(args);\n+    if (typeof args?.onCompleted === 'function') args.onCompleted({}, null);\n+  };\n+  return [commit, false];\n+};\n+\n+export const createFragmentContainer = (c) => c;\n+export const createRefetchContainer = (c) => c;\n+export const createPaginationContainer = (c) => c;\n+export const useLazyLoadQuery = () => (globalThis.__HARBOR_PRELOADED__ ?? {});\n+export const QueryRenderer = () => null;\n+export const RelayEnvironmentProvider = ({ children }) => children;\n+export default { graphql, useFragment, usePreloadedQuery, useQueryLoader, useMutation };\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/reactRouterDom.jsx b/opencti-platform/opencti-front/harbor_tests/stubs/reactRouterDom.jsx\nnew file mode 100644\nindex 0000000..0f411c0\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/reactRouterDom.jsx\n@@ -0,0 +1,16 @@\n+// Stand-in for react-router-dom (not installed offline). <Routes>/<Route> render nothing (the\n+// spec looks at the page chrome above the router outlet, not at the routed screens); the rest\n+// is enough for the REAL DraftRoot to run: it reads the draft id from useParams and the current\n+// tab from useLocation().pathname.\n+import React from 'react';\n+export const Link = ({ to, children, ...rest }) => <a href={typeof to === 'string' ? to : '#'} {...rest}>{children}</a>;\n+export const NavLink = Link;\n+export const Navigate = () => null;\n+export const Route = () => null;\n+export const Routes = () => null;\n+export const Outlet = () => null;\n+export const MemoryRouter = ({ children }) => children;\n+export const useNavigate = () => () => {};\n+export const useLocation = () => ({ pathname: globalThis.__HARBOR_PATHNAME__ ?? '/', search: '', hash: '', state: null });\n+export const useParams = () => (globalThis.__HARBOR_PARAMS__ ?? {});\n+export default { Link, Navigate, Route, Routes, useLocation, useParams };\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/relayEnvironment.js b/opencti-platform/opencti-front/harbor_tests/stubs/relayEnvironment.js\nnew file mode 100644\nindex 0000000..e99e89e\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/relayEnvironment.js\n@@ -0,0 +1,17 @@\n+// Stand-in for src/relay/environment (the real one builds a relay Environment against a live\n+// GraphQL endpoint). MESSAGING$ is the snackbar bus used by the REAL useApiMutation.\n+export const APP_BASE_PATH = '';\n+export const MESSAGING$ = {\n+  notifySuccess: () => {},\n+  notifyError: () => {},\n+  notifyRelayError: () => {},\n+  notifyCustomRelayError: () => {},\n+  toastError: () => {},\n+  toggleNav: { subscribe: () => ({ unsubscribe: () => {} }) },\n+};\n+export const relayErrorHandling = () => {};\n+export const environment = {};\n+export const commitMutation = () => {};\n+export const fetchQuery = () => ({ toPromise: async () => ({}) });\n+export const QueryRenderer = () => null;\n+export default { environment, commitMutation, fetchQuery, APP_BASE_PATH, MESSAGING$ };\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/relayRuntime.js b/opencti-platform/opencti-front/harbor_tests/stubs/relayRuntime.js\nnew file mode 100644\nindex 0000000..19f3968\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/relayRuntime.js\n@@ -0,0 +1,6 @@\n+// Stand-in for `relay-runtime` (absent offline); only the graphql tag is ever used as a value.\n+export const graphql = (strings, ...exprs) => ({ kind: 'Request', __harborGraphQL: String.raw({ raw: strings }, ...exprs) });\n+export const ConnectionHandler = { getConnection: () => null, createEdge: () => null, insertEdgeBefore: () => {} };\n+export const commitMutation = () => {};\n+export const fetchQuery = () => ({ toPromise: async () => ({}) });\n+export default { graphql, ConnectionHandler };\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/rxjs.js b/opencti-platform/opencti-front/harbor_tests/stubs/rxjs.js\nnew file mode 100644\nindex 0000000..3e8c02a\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/rxjs.js\n@@ -0,0 +1,5 @@\n+// Stand-in for `rxjs` (absent offline). Both DraftRoot and ConnectorWorks subscribe to an\n+// interval to auto-refresh; the spec asserts on the first render, so the ticks never matter.\n+export const interval = () => ({ subscribe: () => ({ unsubscribe: () => {} }) });\n+export const Subject = class { subscribe() { return { unsubscribe: () => {} }; } next() {} };\n+export default { interval, Subject };\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/security.jsx b/opencti-platform/opencti-front/harbor_tests/stubs/security.jsx\nnew file mode 100644\nindex 0000000..f9bc53f\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/security.jsx\n@@ -0,0 +1,6 @@\n+// Stand-in for utils/Security (the real one reads the logged-in user through useAuth + relay).\n+const Security = ({ children, placeholder = null, hasAccess = true }) => (hasAccess ? children : placeholder);\n+export const CollaborativeSecurity = ({ children }) => children;\n+export const granted = () => true;\n+export const CAPABILITY_INFORMATION = {};\n+export default Security;\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/time.js b/opencti-platform/opencti-front/harbor_tests/stubs/time.js\nnew file mode 100644\nindex 0000000..937602b\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/time.js\n@@ -0,0 +1,10 @@\n+// Stand-in for utils/Time (moment-timezone + date-fns are absent offline). Only the polling\n+// interval constants are reached from the modules under test.\n+export const ONE_SECOND = 1000;\n+export const FIVE_SECONDS = 5000;\n+export const TEN_SECONDS = 10000;\n+export const FIVE_MINUTES = 300000;\n+export const now = () => new Date(0).toISOString();\n+export const dayStartDate = () => new Date(0);\n+export const dateFiltersValueForDisplay = (v) => v;\n+export default { FIVE_SECONDS, TEN_SECONDS };\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/useDraftContext.js b/opencti-platform/opencti-front/harbor_tests/stubs/useDraftContext.js\nnew file mode 100644\nindex 0000000..683e17c\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/useDraftContext.js\n@@ -0,0 +1,4 @@\n+// Stand-in for utils/hooks/useDraftContext (reads the current draft off the relay store).\n+// Returns whatever the spec published, so the REAL DraftRoot keeps its own read-only branching.\n+const useDraftContext = () => (globalThis.__HARBOR_DRAFT_CONTEXT__ ?? null);\n+export default useDraftContext;\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/useGranted.js b/opencti-platform/opencti-front/harbor_tests/stubs/useGranted.js\nnew file mode 100644\nindex 0000000..a6b9011\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/useGranted.js\n@@ -0,0 +1,9 @@\n+// Stand-in for utils/hooks/useGranted (relay-backed capabilities of the logged-in user).\n+const useGranted = () => true;\n+export const BYPASS = 'BYPASS';\n+export const MODULES_MODMANAGE = 'MODULES_MODMANAGE';\n+export const KNOWLEDGE_KNASKIMPORT = 'KNOWLEDGE_KNASKIMPORT';\n+export const KNOWLEDGE_KNUPDATE = 'KNOWLEDGE_KNUPDATE';\n+export const KNOWLEDGE_KNPARTICIPATE = 'KNOWLEDGE_KNPARTICIPATE';\n+export const KNOWLEDGE_KNUPDATE_KNORGARESTRICT = 'KNOWLEDGE_KNUPDATE_KNORGARESTRICT';\n+export default useGranted;\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/useHelper.js b/opencti-platform/opencti-front/harbor_tests/stubs/useHelper.js\nnew file mode 100644\nindex 0000000..5b713b8\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/useHelper.js\n@@ -0,0 +1,7 @@\n+// Stand-in for utils/hooks/useHelper (feature flags come from the platform settings over relay).\n+const useHelper = () => ({\n+  isFeatureEnable: (flag) => (globalThis.__HARBOR_FEATURES__ ?? []).includes(flag),\n+  isRuntimeFieldEnable: () => false,\n+  isSortableAttribute: () => false,\n+});\n+export default useHelper;\ndiff --git a/opencti-platform/opencti-front/harbor_tests/stubs/useSwitchDraft.js b/opencti-platform/opencti-front/harbor_tests/stubs/useSwitchDraft.js\nnew file mode 100644\nindex 0000000..cf64414\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/stubs/useSwitchDraft.js\n@@ -0,0 +1,4 @@\n+// Stand-in for private/components/drafts/useSwitchDraft (a relay mutation that moves the\n+// session into draft mode).\n+const useSwitchDraft = () => ({ enterDraft: () => {}, exitDraft: () => {} });\n+export default useSwitchDraft;\ndiff --git a/opencti-platform/opencti-front/harbor_tests/vitest.config.mts b/opencti-platform/opencti-front/harbor_tests/vitest.config.mts\nnew file mode 100644\nindex 0000000..8729d82\n--- /dev/null\n+++ b/opencti-platform/opencti-front/harbor_tests/vitest.config.mts\n@@ -0,0 +1,117 @@\n+// Harbor verifier vitest config (synthetic, added by test.patch).\n+//\n+// The opencti-front app cannot be booted wholesale in jsdom: the production entry graph pulls in\n+// react-relay, generated __generated__/*.graphql artifacts, @mui/styles, ramda, moment-timezone,\n+// rxjs, react-router-dom ... none of which are present in the offline verifier image.\n+//\n+// So we load the REAL modules that make up the feature under test -- DraftRoot (the draft page\n+// that owns the call site), ConnectorWorkLine (the shared work line that owns the field labels),\n+// ConnectorWorks (the OTHER, generic call site on the connectors page), plus the real Label,\n+// TaskStatus, Tag and useApiMutation -- and substitute small stand-ins only for the LEAF modules\n+// around them.\n+//\n+// Substitution is done with a resolveId plugin keyed on the RESOLVED path suffix rather than on\n+// the literal import specifier, so it keeps working whether a module is imported as\n+// '../../../../components/i18n', '@components/data/connectors/...' or '@common/button/Button',\n+// and it survives the alias plugin rewriting the specifier to an absolute path.\n+//\n+// NOTE on the aliases: opencti-front's tsconfig maps @components/* to src/PRIVATE/components/*\n+// (not src/components/*) and @common/* to src/components/common/*.\n+import { defineConfig } from 'vitest/config';\n+import react from '@vitejs/plugin-react';\n+import path from 'node:path';\n+import { fileURLToPath } from 'node:url';\n+\n+const here = path.dirname(fileURLToPath(import.meta.url));\n+const root = path.resolve(here, '..');\n+const stub = (f: string) => path.join(here, 'stubs', f);\n+\n+// Bare package specifiers that are simply absent from the offline image.\n+const BARE_STUBS: Record<string, string> = {\n+  'react-relay': stub('reactRelay.jsx'),\n+  'relay-runtime': stub('relayRuntime.js'),\n+  'react-router-dom': stub('reactRouterDom.jsx'),\n+  rxjs: stub('rxjs.js'),\n+  ramda: stub('ramda.js'),\n+  dompurify: stub('dompurify.js'),\n+  'js-base64': stub('jsBase64.js'),\n+  'mdi-material-ui': stub('mdiMaterialUi.jsx'),\n+  '@mui/icons-material': stub('muiIcons.jsx'),\n+  '@mui/styles': stub('muiStyles.js'),\n+  '@mui/styles/makeStyles': stub('makeStyles.js'),\n+};\n+\n+// First-party modules replaced by stand-ins, keyed on their path under opencti-front/src.\n+//\n+// NOTE what is NOT in this map and therefore runs for real:\n+//   private/components/drafts/DraftRoot                    <- call site the fix touches\n+//   private/components/data/connectors/ConnectorWorkLine   <- component the fix touches\n+//   private/components/data/connectors/ConnectorWorks      <- the OTHER call site (p2p anchor)\n+//   components/common/label/Label                          <- renders every field label\n+//   components/TaskStatus + components/common/tag/Tag      <- renders the status value\n+//   utils/hooks/useApiMutation, utils/String, utils/tabUtils\n+const SRC_STUBS: Record<string, string> = {\n+  'components/i18n': stub('i18n.jsx'),\n+  'components/Loader': stub('loader.jsx'),\n+  'components/ErrorNotFound': stub('noopComponent.jsx'),\n+  'components/Breadcrumbs': stub('noopComponent.jsx'),\n+  'components/common/button/Button': stub('Button.jsx'),\n+  'components/common/card/Card': stub('Card.jsx'),\n+  'components/common/card/CardTitle': stub('CardTitle.jsx'),\n+  'private/components/common/drawer/Drawer': stub('Drawer.jsx'),\n+  'private/components/data/connectors/ConnectorWorksErrorLine': stub('noopComponent.jsx'),\n+  'private/components/data/connectors/parseWorkErrors': stub('parseWorkErrors.js'),\n+  'private/components/data/import/ImportFilesContent': stub('noopComponent.jsx'),\n+  'private/components/drafts/DraftEntities': stub('noopComponent.jsx'),\n+  'private/components/drafts/DraftRelationships': stub('noopComponent.jsx'),\n+  'private/components/drafts/DraftSightings': stub('noopComponent.jsx'),\n+  'private/components/drafts/DraftReview': stub('noopComponent.jsx'),\n+  'private/components/drafts/DraftOverview': stub('noopComponent.jsx'),\n+  'private/components/drafts/useSwitchDraft': stub('useSwitchDraft.js'),\n+  'relay/environment': stub('relayEnvironment.js'),\n+  'utils/Security': stub('security.jsx'),\n+  'utils/Time': stub('time.js'),\n+  'utils/hooks/useGranted': stub('useGranted.js'),\n+  'utils/hooks/useDraftContext': stub('useDraftContext.js'),\n+  'utils/hooks/useHelper': stub('useHelper.js'),\n+};\n+\n+const srcDir = path.join(root, 'src');\n+\n+function harborStubs() {\n+  return {\n+    name: 'harbor-stubs',\n+    enforce: 'pre' as const,\n+    resolveId(source: string, importer?: string) {\n+      if (Object.prototype.hasOwnProperty.call(BARE_STUBS, source)) return BARE_STUBS[source];\n+      let abs: string | null = null;\n+      if (path.isAbsolute(source)) abs = source;\n+      else if (source.startsWith('@common/')) abs = path.join(srcDir, 'components/common', source.slice('@common/'.length));\n+      else if (source.startsWith('@components/')) abs = path.join(srcDir, 'private/components', source.slice('@components/'.length));\n+      else if (source.startsWith('src/')) abs = path.join(root, source);\n+      else if (source.startsWith('.') && importer) abs = path.resolve(path.dirname(importer), source);\n+      if (!abs) return null;\n+      const rel = path.relative(srcDir, abs).replace(/\\\\/g, '/').replace(/\\.(jsx?|tsx?)$/, '');\n+      return Object.prototype.hasOwnProperty.call(SRC_STUBS, rel) ? SRC_STUBS[rel] : null;\n+    },\n+  };\n+}\n+\n+export default defineConfig({\n+  root,\n+  plugins: [harborStubs(), react()],\n+  resolve: {\n+    alias: [\n+      { find: /^@common\\//, replacement: path.join(srcDir, 'components/common/') },\n+      { find: /^@components\\//, replacement: path.join(srcDir, 'private/components/') },\n+    ],\n+  },\n+  test: {\n+    environment: 'jsdom',\n+    globals: false,\n+    include: ['harbor_tests/**/*.test.jsx'],\n+    setupFiles: [path.join(here, 'setup.js')],\n+    css: false,\n+    testTimeout: 30000,\n+  },\n+});\n", "numLines": 839, "startLine": 1, "totalLines": 839}}

