7	+/*
8	+ * Harbor synthetic spec for OpenCTI-Platform__opencti-16540-mm.
9	+ *
10	+ * WHAT IT DRIVES
11	+ *   - the REAL DraftRoot page (private/components/drafts/DraftRoot.tsx), fed a draft fixture
12	+ *     through the relay boundary, which renders
13	+ *   - the REAL ConnectorWorkLine (private/components/data/connectors/ConnectorWorkLine.tsx) for
14	+ *     the draft's validation work, through the REAL Label / TaskStatus / Tag components, and
15	+ *   - the REAL ConnectorWorks list (the OTHER, generic call site of the very same work line, the
16	+ *     one used by the connectors screen) as the reference context.
17	+ *
18	+ * HOW IT ASSERTS
19	+ *   Never by looking for a string copied out of the fix. A work line is read back as a set of
20	+ *   {label, value} pairs; the status field is located by its VALUE (the work state that the line
21	+ *   is displaying) and the assertion is then made on that field's LABEL. The contract checked is
22	+ *   the observable mapping "which context am I in -> which wording labels the state field":
23	+ *   the draft page must label it with its own validation wording, the generic connectors page
24	+ *   must keep the platform's generic wording, and the two must not collapse onto one text.
25	+ *   The set of work states is read live out of the GraphQL schema's `enum State`, so the spec
26	+ *   follows the platform if a state is ever added or removed.
27	+ */
28	+import fs from 'node:fs';
29	+import path from 'node:path';
30	+import { fileURLToPath } from 'node:url';
31	+import React from 'react';
32	+import { describe, it, expect, afterEach } from 'vitest';
33	+import { render, cleanup } from '@testing-library/react';
34	+import DraftRoot from '../src/private/components/drafts/DraftRoot';
