36	+
37	+const here = path.dirname(fileURLToPath(import.meta.url));
38	+
39	+/* ------------------------------------------------------------------ work states, read live */
40	+
41	+const readWorkStates = () => {
42	+  const schemaPath = path.resolve(here, '../../opencti-graphql/config/schema/opencti.graphql');
43	+  const schema = fs.readFileSync(schemaPath, 'utf-8');
44	+  const block = schema.match(/\benum\s+State\s*\{([^}]*)\}/);
45	+  if (!block) throw new Error(`could not read "enum State" from ${schemaPath}`);
46	+  return block[1].split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('#'));
47	+};
48	+
49	+const WORK_STATES = readWorkStates();
50	+
51	+/* ----------------------------------------------------------------------------- DOM reading */
52	+
53	+// Every field of a work line is a Label (an <h6>) followed by the field value. Walk up from the
54	+// heading to the smallest ancestor that carries more text than the label itself: that node is
55	+// the field. Returns [{ label, value }] in document order.
56	+const fieldsIn = (root) => Array.from(root.querySelectorAll('h6')).map((heading) => {
57	+  const label = (heading.textContent || '').trim();
58	+  let node = heading;
59	+  for (let hop = 0; hop < 3; hop += 1) {
60	+    const parent = node.parentElement;
61	+    if (!parent || parent === root) break;
62	+    // Stop as soon as the parent carries more text than the label: that parent is the field.
63	+    if ((parent.textContent || '').trim() !== label) break;
64	+    node = parent;
65	+  }
66	+  const container = node.parentElement || node;
67	+  const text = (container.textContent || '').trim();
68	+  return { label, value: text.startsWith(label) ? text.slice(label.length).trim() : text };
69	+});
70	+
71	+const labelsIn = (root) => fieldsIn(root).map((f) => f.label);
72	+
73	+// The state field is the one whose displayed VALUE is the work state; its label is what the
74	+// spec is about.
75	+const stateFieldIn = (root, state) => {
76	+  const field = fieldsIn(root).find((f) => f.value === state);
77	+  if (!field) {
78	+    throw new Error(`no field displays the work state "${state}"; fields were ${JSON.stringify(fieldsIn(root))}`);
79	+  }
80	+  return field;
81	+};
