85	+const makeWork = (state, overrides = {}) => ({
86	+  id: 'work-1',
87	+  name: 'Draft validation bundle',
88	+  received_time: '2026-02-03T10:11:12.000Z',
89	+  processed_time: '2026-02-03T10:12:00.000Z',
90	+  completed_time: '2026-02-03T10:13:30.000Z',
91	+  status: state,
92	+  tracking: { import_expected_number: 40, import_processed_number: 12 },
93	+  errors: [],
