95	+});
96	+
97	+const makeDraft = (work, overrides = {}) => ({
98	+  id: 'draft-1',
99	+  name: 'Q1 threat report draft',
100	+  entity_type: 'DraftWorkspace',
101	+  description: 'A draft under validation',
102	+  created_at: '2026-02-03T09:00:00.000Z',
103	+  objectAssignee: [],
104	+  objectParticipant: [],
105	+  createdBy: null,
106	+  objectsCount: {
107	+    containersCount: 1,
108	+    entitiesCount: 2,
109	+    observablesCount: 3,
110	+    relationshipsCount: 4,
111	+    sightingsCount: 5,
112	+    reviewsCount: 6,
113	+    totalCount: 21,
114	+  },
115	+  draft_status: 'validated', // anything but 'open' => the read-only, post-approval overview
116	+  currentUserAccessRight: 'admin',
117	+  authorizedMembers: [],
